import Link from "next/link";
import { notFound } from "next/navigation";
import { requireRolePage, STAFF_ROLES, can } from "@/lib/authz";
import { getVendor, vendorActivities } from "@/server/vendors";
import { formatIN } from "@/lib/format";
import NoteControls from "@/components/admin/NoteControls";
import { updateVendorAction, archiveVendorAction, addVendorNoteAction } from "../actions";

const input = "mt-1 w-full rounded-lg border border-white/20 bg-white/10 px-3 py-2 text-sm text-ailu-cream";
export default async function VendorDetailPage({ params, searchParams }: { params: { id: string }; searchParams: { msg?: string } }) {
  const staff = await requireRolePage(STAFF_ROLES);
  if (!can(staff.role, "vendors.read")) notFound();
  const [vendor, activity] = await Promise.all([getVendor(params.id), vendorActivities(params.id)]);
  if (!vendor) notFound();
  const editable = can(staff.role, "vendors.write");
  const privateFinance = staff.role === "OWNER" || staff.role === "ACCOUNTS";
  return <div className="mx-auto max-w-5xl">
    <Link href="/admin/vendors" className="text-sm text-ailu-cream/60 hover:underline">← Vendors</Link>
    <div className="mt-2 flex flex-wrap items-center gap-3"><h1 className="font-display text-2xl font-bold">{vendor.name}</h1><span className="rounded-full bg-white/10 px-2 py-1 text-xs">{vendor.status.replaceAll("_", " ")}</span>{vendor.archivedAt ? <span className="text-xs text-ailu-cream/50">Archived</span> : null}</div>
    {searchParams.msg ? <p role="status" className="mt-4 rounded-lg border border-ailu-yellow/30 bg-ailu-yellow/10 p-3 text-sm">{searchParams.msg}</p> : null}
    <div className="mt-5 grid gap-4 lg:grid-cols-2">
      <section className="rounded-2xl border border-white/10 bg-[#111114] p-5"><h2 className="font-semibold">Vendor details</h2><dl className="mt-3 space-y-2 text-sm">{[["ID",vendor.id],["Category",vendor.category],["Contact",vendor.contactPerson ?? "—"],["Phone",vendor.phone],["Email",vendor.email ?? "—"],["City",vendor.city ?? "—"],["Rating (internal)",vendor.rating ?? "Not rated"],["Rate notes",vendor.rateNotes ?? "—"],["Tags",vendor.tags.join(", ") || "—"],["Notes",vendor.notes ?? "—"],["Added",formatIN(vendor.createdAt)]].map(([label,value])=><div key={label} className="flex gap-3"><dt className="w-32 shrink-0 text-ailu-cream/50">{label}</dt><dd className="whitespace-pre-wrap">{value}</dd></div>)}{privateFinance && vendor.upiId ? <div className="flex gap-3"><dt className="w-32 shrink-0 text-ailu-cream/50">UPI ID</dt><dd>{vendor.upiId}</dd></div> : null}</dl>
        {staff.role === "OWNER" ? <form action={archiveVendorAction} className="mt-5 border-t border-white/10 pt-4"><input type="hidden" name="id" value={vendor.id}/><input type="hidden" name="archived" value={vendor.archivedAt ? "no" : "yes"}/><button className="text-sm text-ailu-cream/60 underline">{vendor.archivedAt ? "Restore vendor" : "Archive vendor"}</button></form> : null}
      </section>
      {editable ? <section className="rounded-2xl border border-white/10 bg-[#111114] p-5"><h2 className="font-semibold">Edit vendor</h2><form action={updateVendorAction} className="mt-3 grid gap-3 sm:grid-cols-2"><input type="hidden" name="id" value={vendor.id}/>
        <label>Name<input required name="name" defaultValue={vendor.name} maxLength={160} className={input}/></label><label>Category<input required name="category" defaultValue={vendor.category} maxLength={80} className={input}/></label><label>Contact person<input name="contactPerson" defaultValue={vendor.contactPerson ?? ""} className={input}/></label><label>Phone<input required name="phone" defaultValue={vendor.phone} className={input}/></label><label>Alternate phone<input name="altPhone" defaultValue={vendor.altPhone ?? ""} className={input}/></label><label>Email<input name="email" type="email" defaultValue={vendor.email ?? ""} className={input}/></label><label>City<input name="city" defaultValue={vendor.city ?? ""} className={input}/></label><label>GSTIN<input name="gstin" defaultValue={vendor.gstin ?? ""} className={input}/></label><label>Rating<select name="rating" defaultValue={vendor.rating ?? ""} className={input}><option value="" className="text-black">Not rated</option>{[1,2,3,4,5].map((n)=><option key={n} className="text-black">{n}</option>)}</select></label><label>Status<select name="status" defaultValue={vendor.status} className={input}>{["ACTIVE","INACTIVE","DO_NOT_USE"].map((s)=><option key={s} className="text-black">{s}</option>)}</select></label>
        {privateFinance ? <label>UPI ID<input name="upiId" defaultValue={vendor.upiId ?? ""} className={input}/></label> : null}
        <label className="sm:col-span-2">Address<textarea name="address" defaultValue={vendor.address ?? ""} className={input}/></label><label className="sm:col-span-2">Rate notes<textarea name="rateNotes" defaultValue={vendor.rateNotes ?? ""} className={input}/></label><label className="sm:col-span-2">Tags (comma separated)<input name="tags" defaultValue={vendor.tags.join(", ")} className={input}/></label><label className="sm:col-span-2">Notes<textarea name="notes" defaultValue={vendor.notes ?? ""} className={input}/></label><button className="rounded-lg border border-ailu-yellow/60 px-4 py-2 font-semibold text-ailu-yellow">Save vendor</button>
      </form></section> : null}
    </div>
    <section className="mt-5 rounded-2xl border border-white/10 bg-[#111114] p-5"><h2 className="font-semibold">Event history ({vendor.bookings.length})</h2>{vendor.bookings.length ? <ul className="mt-3 space-y-2">{vendor.bookings.map((booking)=><li key={booking.id} className="flex flex-wrap items-center gap-2 rounded-lg border border-white/10 p-3 text-sm"><Link href={`/admin/events/${booking.event.id}`} className="text-ailu-yellow hover:underline">{booking.event.title}</Link><span className="text-ailu-cream/60">{booking.service}</span><span className="ml-auto text-xs">{booking.status}</span></li>)}</ul> : <p className="mt-2 text-sm text-ailu-cream/50">No event bookings yet.</p>}</section>
    <section id="notes" className="mt-5 rounded-2xl border border-white/10 bg-[#111114] p-5"><h2 className="font-semibold">Vendor notes</h2>{can(staff.role, "vendors.note") ? <form action={addVendorNoteAction} className="mt-3"><input type="hidden" name="id" value={vendor.id}/><label className="block text-sm">Add a timeline note<textarea required name="note" rows={3} maxLength={2000} className={input}/></label><button className="mt-2 rounded-lg border border-ailu-yellow/60 px-4 py-2 text-sm font-semibold text-ailu-yellow">Add note</button></form> : null}{activity.length ? <ul className="mt-4 space-y-2 text-sm">{activity.map((item)=><li key={item.id} className="rounded-lg border border-white/10 p-3"><time className="text-xs text-ailu-cream/50">{formatIN(item.at)}</time><p className="mt-1 whitespace-pre-wrap">{item.body}</p><NoteControls note={item} staff={staff} back={`/admin/vendors/${vendor.id}#notes`} /></li>)}</ul> : <p className="mt-3 text-sm text-ailu-cream/50">No timeline notes yet.</p>}</section>
  </div>;
}
